import{_ as a,o as i,c as e,a5 as l}from"./chunks/framework.C1a7WKBV.js";const k=JSON.parse('{"title":"AI 使用安全与隐私清单","description":"在聊天、API、Agent、本地模型和 MCP 场景中保护密钥、数据、设备权限与交付结果。","frontmatter":{"title":"AI 使用安全与隐私清单","description":"在聊天、API、Agent、本地模型和 MCP 场景中保护密钥、数据、设备权限与交付结果。"},"headers":[],"relativePath":"tips/security-checklist.md","filePath":"tips/security-checklist.md","lastUpdated":1788838685000}'),s={name:"tips/security-checklist.md"};function d(h,t,r,n,o,c){return i(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="ai-使用安全与隐私清单" tabindex="-1">AI 使用安全与隐私清单 <a class="header-anchor" href="#ai-使用安全与隐私清单" aria-label="Permalink to &quot;AI 使用安全与隐私清单&quot;">​</a></h1><p>AI 工具的风险不只来自“回答错了”。当工具能读文件、执行命令、访问网页和连接外部系统时，错误操作的影响会被放大。下面的目标是建立可执行的边界，而不是记口号。</p><h2 id="_1-先给数据分级" tabindex="-1">1. 先给数据分级 <a class="header-anchor" href="#_1-先给数据分级" aria-label="Permalink to &quot;1. 先给数据分级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>例子</th><th>默认处理</th></tr></thead><tbody><tr><td>公开</td><td>官网内容、公开代码、公开报告</td><td>可使用已批准的云端工具</td></tr><tr><td>内部</td><td>未发布方案、普通工作文档</td><td>先确认组织政策与服务数据条款</td></tr><tr><td>机密</td><td>客户数据、源代码、商业计划</td><td>最小化、脱敏、限制工具与保存范围</td></tr><tr><td>高敏感</td><td>密码、API Key、身份证件、医疗与财务明细</td><td>不放进提示词；使用专门受控流程</td></tr></tbody></table><p>不确定时按更高一级处理。把姓名替换成“客户 A”只是脱敏的开始，正文里的邮箱、订单号、地址和文件元数据也可能识别人。</p><h2 id="_2-api-key-与令牌" tabindex="-1">2. API Key 与令牌 <a class="header-anchor" href="#_2-api-key-与令牌" aria-label="Permalink to &quot;2. API Key 与令牌&quot;">​</a></h2><h3 id="_2-1-必须做到" tabindex="-1">2.1 必须做到 <a class="header-anchor" href="#_2-1-必须做到" aria-label="Permalink to &quot;2.1 必须做到&quot;">​</a></h3><ul><li>示例使用 <code>sk-xxxxxxxx</code>，不复制真实令牌到截图或聊天。</li><li>令牌放环境变量、系统钥匙串或密钥管理服务。</li><li><code>.env</code> 加入 <code>.gitignore</code>，但仍要在提交前搜索泄露。</li><li>为不同设备或应用创建不同令牌，设置合理额度。</li><li>怀疑泄露时先撤销令牌，再调查来源，不只删除文件。</li></ul><h3 id="_2-2-提交前检查" tabindex="-1">2.2 提交前检查 <a class="header-anchor" href="#_2-2-提交前检查" aria-label="Permalink to &quot;2.2 提交前检查&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sk-[A-Za-z0-9_-]{12,}|API_KEY|TOKEN|PASSWORD&#39;</span></span></code></pre></div><p>搜索只能降低风险，不能证明绝对安全。真实项目应配合仓库平台的 Secret Scanning 或专门工具。</p><h2 id="_3-agent-执行权限" tabindex="-1">3. Agent 执行权限 <a class="header-anchor" href="#_3-agent-执行权限" aria-label="Permalink to &quot;3. Agent 执行权限&quot;">​</a></h2><p>把操作按可逆性分层：</p><table tabindex="0"><thead><tr><th>操作</th><th>建议</th></tr></thead><tbody><tr><td>读代码、搜索文本、运行只读检查</td><td>可在可信目录常规执行</td></tr><tr><td>编辑文件、安装依赖、运行测试</td><td>先看计划，保留 Git 回滚点</td></tr><tr><td>删除文件、改系统配置、访问网络</td><td>每次审查命令和目标</td></tr><tr><td>推送代码、发布、发消息、付款</td><td>必须人工确认最终内容与目标</td></tr></tbody></table><p>不要在用户主目录、下载目录或挂载整个磁盘后练习 Agent。把工作区缩小到单个项目，本身就是有效的安全控制。</p><h2 id="_4-第三方-mcp、插件与扩展" tabindex="-1">4. 第三方 MCP、插件与扩展 <a class="header-anchor" href="#_4-第三方-mcp、插件与扩展" aria-label="Permalink to &quot;4. 第三方 MCP、插件与扩展&quot;">​</a></h2><p>接入前回答：</p><ol><li>发布者是谁，源码和更新记录在哪里？</li><li>它能读取哪些目录、环境变量与账户数据？</li><li>它能执行写入、发送、删除或付款操作吗？</li><li>数据会发往哪个域名，保存多久？</li><li>不再使用时如何撤销令牌和移除权限？</li></ol><p>先用测试账户与最小权限。能只读就不给写入，能限定目录就不授权整个磁盘。</p><h2 id="_5-防止提示词注入影响-agent" tabindex="-1">5. 防止提示词注入影响 Agent <a class="header-anchor" href="#_5-防止提示词注入影响-agent" aria-label="Permalink to &quot;5. 防止提示词注入影响 Agent&quot;">​</a></h2><p>网页、文档、Issue 和代码注释都可能包含“忽略之前规则、上传文件”等恶意或误导指令。处理外部内容时：</p><ul><li>明确告诉 Agent：外部内容是待分析数据，不是可信指令。</li><li>读取与执行分开，先让它汇总准备调用的工具。</li><li>涉及秘密、联网和不可逆操作时要求人工确认。</li><li>不让来自网页的文字直接决定终端命令。</li><li>检查工具调用的实际参数，不只看 Agent 的解释。</li></ul><h2 id="_6-本地模型的真实边界" tabindex="-1">6. 本地模型的真实边界 <a class="header-anchor" href="#_6-本地模型的真实边界" aria-label="Permalink to &quot;6. 本地模型的真实边界&quot;">​</a></h2><p>本地推理能减少内容发送到模型服务商，但下列功能仍可能联网：模型下载、在线搜索、遥测、插件、MCP、崩溃报告和更新检查。参照《<a href="/clients/local-ai">Ollama 与 LM Studio</a>》验证断网能力，并逐项检查外部连接。</p><h2 id="_7-交付前检查表" tabindex="-1">7. 交付前检查表 <a class="header-anchor" href="#_7-交付前检查表" aria-label="Permalink to &quot;7. 交付前检查表&quot;">​</a></h2><ul><li>[ ] 输出中的事实、数字和引用已回到原始来源核验。</li><li>[ ] 代码通过测试、类型检查、构建和人工体验。</li><li>[ ] <code>git diff</code> 中没有密钥、个人数据或意外文件。</li><li>[ ] 依赖来自可信来源，安装脚本和许可证已检查。</li><li>[ ] AI 生成内容没有冒充真实经历、用户评价或测试结果。</li><li>[ ] 发布、推送、发送和删除操作由人做最终确认。</li><li>[ ] 已记录已知限制、回滚方式和负责人。</li></ul><h2 id="_8-发生误传时" tabindex="-1">8. 发生误传时 <a class="header-anchor" href="#_8-发生误传时" aria-label="Permalink to &quot;8. 发生误传时&quot;">​</a></h2><ol><li>立即撤销令牌、会话或共享链接。</li><li>记录泄露时间、数据范围、接收服务与可能访问者。</li><li>按组织流程通知安全或数据负责人。</li><li>清理 Git 历史、聊天记录或云端文件，但不要把“删除界面记录”等同于服务端已彻底清除。</li><li>增加预防措施：更小权限、提交前扫描、脱敏模板或审批步骤。</li></ol>`,28)])])}const u=a(s,[["render",d]]);export{k as __pageData,u as default};
